import Foundation
import XCTest
@testable import ColorComposerCore

/// Replays the versioned golden vectors generated by
/// `viamin/color_matching`'s `mix parity.generate` task.
final class SolverParityCorpusTests: XCTestCase {
    func testWeightedSquaredErrorMatchesParityCorpusExactly() throws {
        let corpus = try loadCorpus()

        XCTAssertEqual(corpus.algorithmVersion, 1)
        XCTAssertEqual(corpus.scorer, "ColorMatching.WeightedSquaredError")
        XCTAssertEqual(corpus.selection, "earliest-index-wins")
        XCTAssertEqual(corpus.missingPolicy, "excluded-when-any-positive-weight-channel-missing")

        for scenario in corpus.scenarios {
            try assertScoresMatch(scenario)
            try assertSelectionMatches(scenario)
        }
    }

    private func assertScoresMatch(_ scenario: ParityScenario) throws {
        let scorer = WeightedSquaredErrorScorer()
        let target = TargetResponseVector(channels(from: scenario.target.channels))
        let weights = weights(from: scenario.weights)

        XCTAssertEqual(scenario.palette.count, scenario.expected.scores.count, scenario.id)

        for (candidate, expected) in zip(scenario.palette, scenario.expected.scores) {
            XCTAssertEqual(candidate.index!, expected.index, scenario.id)

            switch (scorer.score(candidate: paletteColor(from: candidate), target: target, weights: weights), expected.score) {
            case (.excluded, .excluded):
                break
            case (.score(let actual), .value(let expected)):
                XCTAssertEqual(actual, expected, scenario.id)
            default:
                XCTFail("\(scenario.id): score for candidate \(candidate.index) differs from corpus")
            }
        }
    }

    private func assertSelectionMatches(_ scenario: ParityScenario) throws {
        let targetChannels = channels(from: scenario.target.channels)
        let weights = weights(from: scenario.weights)
        let palette = scenario.palette.map(paletteColor)
        let expected = scenario.expected

        let activeTargetIsComplete = weights.activeConditions.allSatisfy { targetChannels[$0] != nil }
        if activeTargetIsComplete {
            let grids = Dictionary(uniqueKeysWithValues: weights.activeConditions.map {
                ($0, BrightnessGrid(width: 1, height: 1, fill: targetChannels[$0]!))
            })
            let result = try CompositionSolver().solve(palette: palette, sourceGrids: grids, weights: weights)

            XCTAssertEqual(result.colorIndex(x: 0, y: 0), expected.selectedIndex, scenario.id)
            if let selectedIndex = expected.selectedIndex {
                XCTAssertEqual(palette[selectedIndex].hex, expected.selectedHexColor!, scenario.id)
                XCTAssertEqual(result.error(x: 0, y: 0), expected.error!, scenario.id)
            } else {
                XCTAssertNil(expected.error, scenario.id)
                XCTAssertTrue(result.error(x: 0, y: 0).isInfinite, scenario.id)
            }
        } else {
            // A source grid cannot represent an absent target measurement.
            // Replay the scorer directly and retain the corpus's earliest-wins rule.
            let scorer = WeightedSquaredErrorScorer()
            let target = TargetResponseVector(targetChannels)
            let selected = palette.enumerated().first(where: { entry in
                if case .score = scorer.score(candidate: entry.element, target: target, weights: weights) { return true }
                return false
            })?.offset
            XCTAssertEqual(selected, expected.selectedIndex, scenario.id)
        }

        XCTAssertEqual(expected.tiedIndices.first, expected.selectedIndex, scenario.id)
        if let tieBroke = expected.tieBroke {
            XCTAssertEqual(tieBroke, expected.tiedIndices.count > 1, scenario.id)
        }
    }

    private func loadCorpus() throws -> ParityCorpus {
        let testFile = URL(fileURLWithPath: #filePath)
        let fixture = testFile
            .deletingLastPathComponent()
            .appendingPathComponent("Fixtures/solver-parity-v1.json")
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(ParityCorpus.self, from: Data(contentsOf: fixture))
    }

    private func paletteColor(from entry: ParityEntry) -> PaletteColor {
        PaletteColor(
            id: entry.index ?? -1,
            hex: entry.hexColor,
            rgb: RGBColor(hex: entry.hexColor)!,
            responses: channels(from: entry.channels).mapValues(IlluminationResponse.init(brightness:))
        )
    }

    private func channels(from values: [String: Double]) -> [LightingCondition: Double] {
        Dictionary(uniqueKeysWithValues: values.compactMap { key, value in
            LightingCondition(rawValue: key).map { ($0, value) }
        })
    }

    private func weights(from values: [String: Double]) -> ChannelWeights {
        ChannelWeights(
            white: values["white", default: 0],
            red: values["red", default: 0],
            green: values["green", default: 0],
            blue: values["blue", default: 0],
            lps: values["lps", default: 0]
        )
    }
}

private struct ParityCorpus: Decodable {
    let algorithmVersion: Int
    let scorer: String
    let selection: String
    let missingPolicy: String
    let scenarios: [ParityScenario]
}

private struct ParityScenario: Decodable {
    let id: String
    let weights: [String: Double]
    let target: ParityEntry
    let palette: [ParityEntry]
    let expected: ParityExpected
}

private struct ParityEntry: Decodable {
    let index: Int?
    let hexColor: String
    let channels: [String: Double]
}

private struct ParityExpected: Decodable {
    let error: Double?
    let scores: [ParityScore]
    let selectedHexColor: String?
    let selectedIndex: Int?
    let tieBroke: Bool?
    let tiedIndices: [Int]
}

private struct ParityScore: Decodable {
    let index: Int
    let score: ParityScoreValue
}

private enum ParityScoreValue: Decodable {
    case excluded
    case value(Double)

    init(from decoder: Decoder) throws {
        let container = try decoder.singleValueContainer()
        if let value = try? container.decode(Double.self) {
            self = .value(value)
        } else if try container.decode(String.self) == "excluded" {
            self = .excluded
        } else {
            throw DecodingError.dataCorruptedError(in: container, debugDescription: "Expected a score or excluded")
        }
    }
}
